
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mggac_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mggac", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.887424499604205e+00, -4.788686576561980e+00, -4.650307752159187e+00, -4.458570332764156e+00, -4.197203152057116e+00, -3.849136836266474e+00, -3.400727714094824e+00, -2.849382351697391e+00, -2.212723124590329e+00, -1.508957664201444e+00, -8.362865135858879e-01, -6.360267688929836e-01, -6.291976935399090e-01, -5.331020924748116e-01, -3.630008488277305e-01, -1.955547602779411e-01, -8.058991588782666e-02, -2.636127345020544e-02, -5.628141510064075e-03, -6.317669718585785e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


